<?php // Property visit scheduling UI. ?>
<style>
.vis-card{background:#fff;border:1px solid #e3e8ef;border-radius:14px;padding:22px}.vis-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:15px}.vis-field{display:flex;flex-direction:column;gap:7px}.vis-field.wide{grid-column:1/-1}.vis-field label{font-size:12px;font-weight:700;color:#34465c}.vis-field input,.vis-field select,.vis-field textarea{width:100%;min-height:42px;padding:10px;border:1px solid #d9e1eb;border-radius:8px;font:inherit;font-size:12px}.vis-btn{border:0;border-radius:8px;padding:11px 16px;background:#2463a6;color:white;font:inherit;font-size:12px;cursor:pointer}@media(max-width:800px){.vis-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:560px){.vis-grid{grid-template-columns:1fr}.vis-field.wide{grid-column:auto}.vis-card{padding:15px}}
</style>
<form class="vis-card" id="visitForm"><h2 style="font-size:16px;margin:0 0 18px">تنظیم بازدید ملک</h2><div class="vis-grid">
<div class="vis-field"><label>کد یا آدرس ملک</label><input name="property" required></div><div class="vis-field"><label>نام مشتری</label><input name="customer" required></div><div class="vis-field"><label>شماره تماس</label><input name="phone" type="tel"></div>
<div class="vis-field"><label>تاریخ بازدید</label><input name="visit_date" type="date" required></div><div class="vis-field"><label>ساعت بازدید</label><input name="visit_time" type="time" required></div><div class="vis-field"><label>کارمند مسئول</label><input name="staff" placeholder="نام کارمند"></div>
<div class="vis-field"><label>وضعیت بازدید</label><select name="status"><option>برنامه‌ریزی‌شده</option><option>انجام‌شده</option><option>لغو‌شده</option><option>نیازمند بازدید دوباره</option></select></div><div class="vis-field"><label>وقت بعدی</label><input name="next_visit" type="datetime-local"></div><div class="vis-field"><label>نتیجه بازدید</label><select name="result"><option>در انتظار</option><option>علاقه‌مند</option><option>علاقه‌مند نیست</option><option>پیشنهاد می‌دهد</option><option>بازدید دوباره</option></select></div>
<div class="vis-field wide"><label>یادداشت بازدید</label><textarea name="notes"></textarea></div>
</div><div style="margin-top:18px"><button class="vis-btn" type="submit">ثبت بازدید</button></div><p id="visitMessage" role="status" style="font-size:12px;line-height:1.8"></p></form>
<script>(function(){const f=document.getElementById('visitForm'),m=document.getElementById('visitMessage');f.addEventListener('submit',e=>{e.preventDefault();m.textContent='جزئیات بازدید بررسی شد؛ دیتابیس وصل نیست و ذخیره دائمی انجام نشد.';m.style.color='#77551a';});})();</script>